460	            ALU_use_PC = FUS[`FU_ALU][`OP_H:`OP_L] == `ALU_AUIPC;
461	            ALU_use_imm = FUS[`FU_ALU][`OP_H];
462	            PC_ctrl = PCR[`FU_ALU];
463	            imm_ctrl = IMM[`FU_ALU];
464	        end
465	        // MEM
466	        else if (FUS[`FU_MEM][`RDY1] & FUS[`FU_MEM][`RDY2]) begin
467	            ALU_en = 1'b0;
468	            MEM_en = 1'b1;
469	            MUL_en = 1'b0;
470	            DIV_en = 1'b0;
471	            JUMP_en = 1'b0;
472	
473	            MEM_we = FUS[`FU_MEM][`OP_L];
474	            MEM_bhw = FUS[`FU_MEM][`OP_L+3:`OP_L+1];
475	            rs1_ctrl = FUS[`FU_MEM][`SRC1_H:`SRC1_L];
476	            rs2_ctrl = FUS[`FU_MEM][`SRC2_H:`SRC2_L];   // if store
477	            imm_ctrl = IMM[`FU_MEM];
478	        end
479	        // MUL
480	        else if (FUS[`FU_MUL][`RDY1] & FUS[`FU_MUL][`RDY2]) begin
481	            ALU_en = 1'b0;
482	            MEM_en = 1'b0;
483	            MUL_en = 1'b1;
484	            DIV_en = 1'b0;
485	            JUMP_en = 1'b0;
486	
487	            MUL_op = FUS[`FU_MUL][`OP_L+2:`OP_L];
488	            rs1_ctrl = FUS[`FU_MUL][`SRC1_H:`SRC1_L];
489	            rs2_ctrl = FUS[`FU_MUL][`SRC2_H:`SRC2_L];
490	        end
491	        else if (FUS[`FU_DIV][`RDY1] & FUS[`FU_DIV][`RDY2]) begin
492	            ALU_en = 1'b0;
493	            MEM_en = 1'b0;
494	            MUL_en = 1'b0;
495	            DIV_en = 1'b1;
496	            JUMP_en = 1'b0;
497	            
498	            DIV_op = FUS[`FU_DIV][`OP_L+1:`OP_L];
499	            rs1_ctrl = FUS[`FU_DIV][`SRC1_H:`SRC1_L];
500	            rs2_ctrl = FUS[`FU_DIV][`SRC2_H:`SRC2_L];
501	        end
502	    end
503	
504	    // WB
505	    always @ (*) begin
506	        write_sel = 0;
507	        reg_write = 0;
508	        rd_ctrl = 0;
509	
510	        if (FUS[`FU_JUMP][`FU_DONE] & JUMP_WAR) begin
511	            write_sel = 3'd4;
512	            reg_write = 1'b1;
513	            rd_ctrl = FUS[`FU_JUMP][`DST_H:`DST_L];
514	        end
515	        else if (FUS[`FU_ALU][`FU_DONE] & ALU_WAR) begin
516	            write_sel = 3'd0;
517	            reg_write = 1'b1;
518	            rd_ctrl = FUS[`FU_ALU][`DST_H:`DST_L];
519	        end
520	        else if (FUS[`FU_MEM][`FU_DONE] & MEM_WAR) begin
521	            write_sel = 3'd1;
522	            reg_write = 1'b1;
523	            rd_ctrl = FUS[`FU_MEM][`DST_H:`DST_L];
524	        end
525	        else if (FUS[`FU_MUL][`FU_DONE] & MUL_WAR) begin
526	            write_sel = 3'd2;
527	            reg_write = 1'b1;
528	            rd_ctrl = FUS[`FU_MUL][`DST_H:`DST_L];
529	        end
530	        else if (FUS[`FU_DIV][`FU_DONE] & DIV_WAR) begin
531	            write_sel = 3'd3;
532	            reg_write = 1'b1;
533	            rd_ctrl = FUS[`FU_DIV][`DST_H:`DST_L];
534	        end
535	    end
536	endmodule

