3	module CSRRegs(
4	    input clk, rst,
5	    input[11:0] raddr, waddr,
6	    input[31:0] wdata,
7	    input csr_w,
8	    input[1:0] csr_wsc_mode,
9	    output[31:0] rdata,
10	    output[31:0] mstatus
11	);
12	    // You may need to modify this module for better efficiency
13	    
14	    reg[31:0] CSR [0:15];
15	
16	    // Address mapping. The address is 12 bits, but only 4 bits are used in this module.
17	    wire raddr_valid = raddr[11:7] == 5'h6 && raddr[5:3] == 3'h0;
18	    wire[3:0] raddr_map = (raddr[6] << 3) + raddr[2:0];
19	    wire waddr_valid = waddr[11:7] == 5'h6 && waddr[5:3] == 3'h0;
20	    wire[3:0] waddr_map = (waddr[6] << 3) + waddr[2:0];
21	
22	    assign mstatus = CSR[0];
23	
24	    // CSR read logic (combinational)
25	    assign rdata = raddr_valid ? CSR[raddr_map] : 32'b0;
26	
27	    // CSR write logic: csr_wsc_mode 01 = write, 10 = set, 11 = clear
28	    always@(posedge clk or posedge rst) begin
29	        if(rst) begin
30				CSR[0] <= 32'h88;
31				CSR[1] <= 0;
32				CSR[2] <= 0;
33				CSR[3] <= 0;
34				CSR[4] <= 32'hfff;
35				CSR[5] <= 0;
36				CSR[6] <= 0;
37				CSR[7] <= 0;
38				CSR[8] <= 0;
39				CSR[9] <= 0;
40				CSR[10] <= 0;
41				CSR[11] <= 0;
42				CSR[12] <= 0;
43				CSR[13] <= 0;
44				CSR[14] <= 0;
45				CSR[15] <= 0;
46			end
47			else if(csr_w && waddr_valid) begin
48				case(csr_wsc_mode)
49					2'b01: CSR[waddr_map] <= wdata;
50					2'b10: CSR[waddr_map] <= CSR[waddr_map] | wdata;
51					2'b11: CSR[waddr_map] <= CSR[waddr_map] & ~wdata;
52					default: CSR[waddr_map] <= wdata;
53				endcase
54			end
55	    end
56	endmodule

