3	module ExceptionUnit(
4	    input clk, rst,
5	    input csr_rw_in,
6	    // write/set/clear (funct bits from instruction)
7	    input[1:0] csr_wsc_mode_in,
8	    input csr_w_imm_mux,
9	    input[11:0] csr_rw_addr_in,
10	    input[31:0] csr_w_data_reg,
11	    input[4:0] csr_w_data_imm,
12	    output[31:0] csr_r_data_out,
13	
14	    input interrupt,
15	    input illegal_inst,
16	    input l_access_fault,
17	    input s_access_fault,
18	    input ecall_m,
19	
20	    input mret,
21	
22	    input[31:0] epc_cur,
23	    input[31:0] epc_next,
24	    output[31:0] PC_redirect,
25	    output redirect_mux,
26	
27	    output reg_FD_flush, reg_DE_flush, reg_EM_flush, reg_MW_flush, 
28	    output RegWrite_cancel,
29	    output MemWrite_cancel
30	);
31	    // According to the diagram, design the Exception Unit
32	    // You can modify any code in this file if needed!
33	    reg[11:0] csr_waddr;
34	    reg[31:0] csr_wdata;
35	    reg csr_w;
36	    reg[1:0] csr_wsc;
37	    wire[11:0] csr_raddr;
38	
39	    wire[31:0] mstatus;
40	    wire[31:0] csr_rdata;
41	
42	    CSRRegs csr(.clk(clk),.rst(rst),.csr_w(csr_w),.raddr(csr_raddr),.waddr(csr_waddr),
43	        .wdata(csr_wdata),.rdata(csr_rdata),.mstatus(mstatus),.csr_wsc_mode(csr_wsc));
44	
45	    // ---------------- exception handling logic ----------------
46	    // synchronous exceptions are raised when the faulting instruction reaches WB;
47	    // interrupt is external and refers to the next instruction to execute
48	    wire sync_exc = illegal_inst | ecall_m | l_access_fault | s_access_fault;
49	    wire interrupt_en = interrupt & mstatus[3];     // mstatus.MIE
50	    wire trap = sync_exc | interrupt_en;
51	
52	    // mcause: illegal=2, l_access_fault=5, s_access_fault=7, ecall=11,
53	    //         machine external interrupt=0x8000000b
54	    reg[31:0] cause;
55	    always @(*) begin
56	        if (illegal_inst)         cause = 32'd2;
57	        else if (ecall_m)         cause = 32'd11;
58	        else if (l_access_fault)  cause = 32'd5;
59	        else if (s_access_fault)  cause = 32'd7;
60	        else                      cause = 32'h8000000b;
61	    end
62	
63	    // mepc: faulting instruction for sync exceptions, next PC for interrupt
64	    wire[31:0] mepc_in = sync_exc ? epc_cur : epc_next;
65	    // mtval: no faulting instruction/address information is available
66	    // through the fixed ports of this unit, so it is written as 0
67	    wire[31:0] mtval_in = 32'b0;
68	
69	    // trap entry:  MPP <- 11, MPIE <- MIE, MIE <- 0
70	    wire[31:0] mstatus_trap = {mstatus[31:13], 2'b11, mstatus[10:8],
71	                               mstatus[3], mstatus[6:4], 1'b0, mstatus[2:0]};
72	    // mret:        MPP <- 00, MPIE <- 1, MIE <- MPIE
73	    wire[31:0] mstatus_mret = {mstatus[31:13], 2'b00, mstatus[10:8],
74	                               1'b1, mstatus[6:4], mstatus[7], mstatus[2:0]};
75	
76	    // On a trap several CSRs must be updated through the single write port:
77	    // mepc is written in the detection cycle, then a small FSM writes
78	    // mcause, mtval and mstatus in the following three cycles. The trap
79	    // handler reaches MEM at least 4 cycles after the redirect, so all
80	    // values are in place before they can be read.
81	    localparam ST_IDLE    = 3'd0;
82	    localparam ST_MCAUSE  = 3'd1;
83	    localparam ST_MTVAL   = 3'd2;
84	    localparam ST_MSTATUS = 3'd3;
85	
86	    reg[2:0] state;
87	    reg[31:0] saved_cause, saved_mtval, saved_mstatus;
88	
89	    // CSR read address: trap -> mtvec, mret -> mepc, otherwise the
90	    // address of the CSR instruction currently in MEM
91	    assign csr_raddr = trap ? 12'h305 :
92	                       mret ? 12'h341 : csr_rw_addr_in;
93	    assign csr_r_data_out = csr_rdata;
94	
95	    // PC redirect: trap -> mtvec, mret -> mepc (both via csr_rdata)
96	    assign PC_redirect = csr_rdata;
97	    assign redirect_mux = trap | mret;
98	
99	    // pipeline flush: a trap kills every in-flight instruction (the one in
100	    // WB is cancelled below); mret only kills the younger wrong-path ones
101	    assign reg_FD_flush = trap | mret;
102	    assign reg_DE_flush = trap | mret;
103	    assign reg_EM_flush = trap | mret;
104	    assign reg_MW_flush = trap;
105	    assign RegWrite_cancel = trap;
106	    assign MemWrite_cancel = trap;
107	
108	    // normal CSR instruction write (MEM stage). For set/clear modes a zero
109	    // source (rs1 = x0 / uimm = 0) must not modify the CSR.
110	    wire csr_w_normal = csr_rw_in & ~(csr_wsc_mode_in[1] & (csr_w_data_imm == 5'b0));
111	    wire[31:0] csr_wdata_normal = csr_w_imm_mux ? {27'b0, csr_w_data_imm} : csr_w_data_reg;
112	
113	    // CSR write port mux: trap/FSM/mret have priority over normal CSR writes
114	    always @(*) begin
115	        if (trap) begin
116	            csr_w = 1'b1; csr_waddr = 12'h341; csr_wdata = mepc_in; csr_wsc = 2'b01;
117	        end
118	        else if (state == ST_MCAUSE) begin
119	            csr_w = 1'b1; csr_waddr = 12'h342; csr_wdata = saved_cause; csr_wsc = 2'b01;
120	        end
121	        else if (state == ST_MTVAL) begin
122	            csr_w = 1'b1; csr_waddr = 12'h343; csr_wdata = saved_mtval; csr_wsc = 2'b01;
123	        end
124	        else if (state == ST_MSTATUS) begin
125	            csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = saved_mstatus; csr_wsc = 2'b01;
126	        end
127	        else if (mret) begin
128	            csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = mstatus_mret; csr_wsc = 2'b01;
129	        end
130	        else begin
131	            csr_w = csr_w_normal; csr_waddr = csr_rw_addr_in;
132	            csr_wdata = csr_wdata_normal; csr_wsc = csr_wsc_mode_in;
133	        end
134	    end
135	
136	    always @(posedge clk or posedge rst) begin
137	        if (rst) begin
138	            state <= ST_IDLE;
139	            saved_cause <= 0;
140	            saved_mtval <= 0;
141	            saved_mstatus <= 0;
142	        end
143	        else if (trap) begin
144	            state <= ST_MCAUSE;
145	            saved_cause <= cause;
146	            saved_mtval <= mtval_in;
147	            saved_mstatus <= mstatus_trap;
148	        end
149	        else if (state == ST_MCAUSE)  state <= ST_MTVAL;
150	        else if (state == ST_MTVAL)   state <= ST_MSTATUS;
151	        else if (state == ST_MSTATUS) state <= ST_IDLE;
152	    end
153	
154	endmodule

1	`timescale 1ns / 1ps
2	`include "CtrlDefine.vh"
3	
4	// Reservation station for one functional unit type.
5	// Entry layout (see CtrlDefine.vh):
6	//   | BUSY | OP | Q1 | Q2 | V1 | V2 | A | PC |
7	// An 8-bit tag {FU[2:0], index+1} identifies each entry on the CDB and in
8	// the RAT; 8'b0 means "no dependency".
9	// An entry is freed only when its result is broadcast on the CDB, so a tag
10	// is never reused while an older instruction still references it.
11	module RS #(
12	    parameter FU = `FU_ALU,
13	    parameter num = 3
14	)(
15	    input clk,
16	    input rst,
17	
18	    // issue interface
19	    input selected,             // allocate an entry for the instr in IS
20	    output [7:0] free_rs,       // tag of a free entry, 0 if none
21	    input [4:0] op,
22	    input [7:0] Qj, Qk,         // RAT lookup results (0 = value already valid)
23	    input [31:0] Vj, Vk,        // operand values (register file / imm / PC)
24	    input [31:0] A,             // immediate
25	    input [31:0] pc_IS,         // PC of the instr in IS
26	
27	    // dispatch interface (to FU)
28	    output en_FU,               // one-cycle pulse
29	    output [31:0] vj, vk,
30	    output [4:0] op_out,
31	    output [31:0] A_o,
32	    output [31:0] pc_FU,        // PC of the instr currently in the FU
33	    output reg [7:0] cdb_rs_rd, // tag of the instr currently in the FU
34	
35	    // CDB broadcast
36	    input [7:0] cdb_rs_num,
37	    input [31:0] cdb_data,
38	
39	    output [31:0] pc_debug
40	);
41	
42	    reg [159:0] entry [0:num-1];
43	    reg [num-1:0] dispatched;   // entry sent to FU, waiting for CDB
44	    reg fu_busy;                // FU is executing an instruction
45	    reg [31:0] pc_reg;
46	
47	    integer i;
48	
49	    function [7:0] tag_of;
50	        input integer idx;
51	        tag_of = (FU << 5) | (idx + 1);
52	    endfunction
53	
54	    // ---- free entry allocation (lowest index first) ----
55	    reg [7:0] free_tag;
56	    integer free_idx;
57	    always @ (*) begin
58	        free_tag = 8'b0;
59	        free_idx = 0;
60	        for (i = num - 1; i >= 0; i = i - 1) begin
61	            if (~entry[i][`BUSY]) begin
62	                free_tag = tag_of(i);
63	                free_idx = i;
64	            end
65	        end
66	    end
67	    assign free_rs = free_tag;
68	
69	    // ---- ready entry selection (lowest index first) ----
70	    integer disp_idx;
71	    reg disp_found;
72	    always @ (*) begin
73	        disp_found = 1'b0;
74	        disp_idx = 0;
75	        for (i = num - 1; i >= 0; i = i - 1) begin
76	            if (entry[i][`BUSY] & ~dispatched[i]
77	                & ~|entry[i][`Q1_H:`Q1_L] & ~|entry[i][`Q2_H:`Q2_L]) begin
78	                disp_found = 1'b1;
79	                disp_idx = i;
80	            end
81	        end
82	    end
83	
84	    assign en_FU  = disp_found & ~fu_busy;
85	    assign vj     = entry[disp_idx][`V1_H:`V1_L];
86	    assign vk     = entry[disp_idx][`V2_H:`V2_L];
87	    assign op_out = entry[disp_idx][`OP_H:`OP_L];
88	    assign A_o    = entry[disp_idx][`A_H:`A_L];
89	    assign pc_FU  = entry[disp_idx][`PC_H:`PC_L]; // combinational: FU latches it at the dispatch edge
90	    assign pc_debug = pc_reg;
91	
92	    // operand values captured at issue; if the needed tag is being broadcast
93	    // on the CDB this very cycle, take the CDB value directly
94	    wire qj_hit = |Qj & (Qj == cdb_rs_num);
95	    wire qk_hit = |Qk & (Qk == cdb_rs_num);
96	    wire [7:0]  Qj_adj = qj_hit ? 8'b0 : Qj;
97	    wire [7:0]  Qk_adj = qk_hit ? 8'b0 : Qk;
98	    wire [31:0] Vj_adj = qj_hit ? cdb_data : Vj;
99	    wire [31:0] Vk_adj = qk_hit ? cdb_data : Vk;
100	
101	    always @ (posedge clk or posedge rst) begin
102	        if (rst) begin
103	            for (i = 0; i < num; i = i + 1) begin
104	                entry[i] <= 160'b0;
105	            end
106	            dispatched <= {num{1'b0}};
107	            fu_busy <= 1'b0;
108	            cdb_rs_rd <= 8'b0;
109	            pc_reg <= 32'b0;
110	        end
111	        else begin
112	            // dispatch to FU
113	            if (en_FU) begin
114	                dispatched[disp_idx] <= 1'b1;
115	                fu_busy <= 1'b1;
116	                cdb_rs_rd <= tag_of(disp_idx);
117	                pc_reg <= entry[disp_idx][`PC_H:`PC_L];
118	            end
119	            else if (fu_busy & |cdb_rs_num & (cdb_rs_num == cdb_rs_rd)) begin
120	                fu_busy <= 1'b0;
121	            end
122	
123	            for (i = 0; i < num; i = i + 1) begin
124	                if (selected & |free_rs & (i == free_idx)) begin
125	                    // allocate: {PC, A, V2, V1, pad, Q2, Q1, pad, OP, BUSY}
126	                    // (entry bits 31:24 and 7:6 are unused, see CtrlDefine.vh)
127	                    entry[i] <= {pc_IS, A, Vk_adj, Vj_adj, 8'b0, Qk_adj, Qj_adj, 2'b0, op, 1'b1};
128	                    dispatched[i] <= 1'b0;
129	                end
130	                else begin
131	                    // CDB broadcast retires the entry it corresponds to
132	                    if (entry[i][`BUSY] & |cdb_rs_num & (cdb_rs_num == tag_of(i))) begin
133	                        entry[i][`BUSY] <= 1'b0;
134	                        dispatched[i] <= 1'b0;
135	                    end
136	                    // operand snoop
137	                    if (entry[i][`BUSY] & ~dispatched[i]) begin
138	                        if (|entry[i][`Q1_H:`Q1_L] & (entry[i][`Q1_H:`Q1_L] == cdb_rs_num)) begin
139	                            entry[i][`V1_H:`V1_L] <= cdb_data;
140	                            entry[i][`Q1_H:`Q1_L] <= 8'b0;
141	                        end
142	                        if (|entry[i][`Q2_H:`Q2_L] & (entry[i][`Q2_H:`Q2_L] == cdb_rs_num)) begin
143	                            entry[i][`V2_H:`V2_L] <= cdb_data;
144	                            entry[i][`Q2_H:`Q2_L] <= 8'b0;
145	                        end
146	                    end
147	                end
148	            end
149	        end
150	    end
151	
152	endmodule

1	`timescale 1ns / 1ps
2	
3	module RAM_B(
4	    input [31:0] addra,
5	    input clka,      // normal clock
6	    input[31:0] dina,
7	    input wea, 
8	    output[31:0] douta,
9	    output [7:0] sim_uart_char_out,
10	    output sim_uart_char_valid,
11	    input[2:0] mem_u_b_h_w
12	);
13	    localparam SIZE = 256;
14	    localparam ADDR_LINE = $clog2(SIZE);
15	    localparam SIM_UART_ADDR = 32'h10000000;
16	
17	    reg[7:0] data[0:SIZE-1];
18	
19	    initial	begin
20	        $readmemh("ram.mem", data);
21	    end
22	
23	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
24	    wire is_uart = addra == SIM_UART_ADDR;
25	    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
26	    wire word_op = mem_u_b_h_w[1];
27	    wire half_op = mem_u_b_h_w[0];
28	    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
29	    wire sign_ext = ~mem_u_b_h_w[2];
30	
31	    // Byte-addressable write logic (UART writes excluded, they only produce
32	    // simulation output). Written on the negative edge so store data latched
33	    // at the positive edge is stable.
34	    always @(negedge clka) begin
35	        if (wea && !is_uart) begin
36	            data[addr] <= dina[7:0];
37	            if (half_op | word_op) begin
38	                data[addr + 1] <= dina[15:8];
39	                if (word_op) begin
40	                    data[addr + 2] <= dina[23:16];
41	                    data[addr + 3] <= dina[31:24];
42	                end
43	            end
44	        end
45	    end
46	
47	    // Byte-addressable read logic with sign/zero extension (little endian).
48	    wire[7:0] b0 = data[addr];
49	    wire[7:0] b1 = data[addr + 1];
50	    wire[7:0] b2 = data[addr + 2];
51	    wire[7:0] b3 = data[addr + 3];
52	    wire[31:0] word_r = {b3, b2, b1, b0};
53	    wire[31:0] half_r = {{16{sign_ext & b1[7]}}, b1, b0};
54	    wire[31:0] byte_r = {{24{sign_ext & b0[7]}}, b0};
55	
56	    assign douta = is_uart ? 32'b0 :
57	                   word_op ? word_r :
58	                   half_op ? half_r :
59	                   byte_r;
60	
61	    // UART simulation output: a write to SIM_UART_ADDR emits dina[7:0] as a
62	    // character; valid pulses for one cycle per write.
63	    reg[7:0] uart_char;
64	    reg uart_valid;
65	
66	    initial begin
67	        uart_char = 8'b0;
68	        uart_valid = 1'b0;
69	    end
70	
71	    always @(negedge clka) begin
72	        if (wea && is_uart) begin
73	            uart_char <= dina[7:0];
74	            uart_valid <= 1'b1;
75	        end
76	        else
77	            uart_valid <= 1'b0;
78	    end
79	
80	    assign sim_uart_char_out = uart_char;
81	    assign sim_uart_char_valid = uart_valid;
82	endmodule

1	`timescale 1ps/1ps
2	
3	module HazardDetectionUnit(
4	    input clk,
5	    input Branch_ID, rs1use_ID, rs2use_ID,
6	    input[1:0] hazard_optype_ID,
7	    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
8	    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
9	        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
10	    output forward_ctrl_ls,
11	    output[1:0] forward_ctrl_A, forward_ctrl_B
12	);
13	    // hazard_optype of the instruction currently in EX / MEM stage
14	    reg [1:0] hazard_optype_EXE, hazard_optype_MEM;
15	    initial begin
16	        hazard_optype_EXE = 2'b00;
17	        hazard_optype_MEM = 2'b00;
18	    end
19	    always @(posedge clk) begin
20	        hazard_optype_EXE <= hazard_optype_ID;
21	        hazard_optype_MEM <= hazard_optype_EXE;
22	    end
23	
24	    // Stall when the EX-stage instruction writes a register the ID instruction reads:
25	    // the value is only forwardable once the producer reaches the MEM stage.
26	    wire rs1_hazard_EXE = rs1use_ID && (rs1_ID != 5'd0) && (rs1_ID == rd_EXE)
27	                          && (hazard_optype_EXE != 2'b00);
28	    wire rs2_hazard_EXE = rs2use_ID && (rs2_ID != 5'd0) && (rs2_ID == rd_EXE)
29	                          && (hazard_optype_EXE != 2'b00);
30	    wire stall = rs1_hazard_EXE | rs2_hazard_EXE;
31	
32	    assign PC_EN_IF     = ~stall;
33	    assign reg_FD_EN    = 1'b1;
34	    assign reg_FD_stall = stall;
35	    assign reg_FD_flush = Branch_ID & ~stall;
36	    assign reg_DE_EN    = 1'b1;
37	    assign reg_DE_flush = stall;
38	    assign reg_EM_EN    = 1'b1;
39	    assign reg_EM_flush = 1'b0;
40	    assign reg_MW_EN    = 1'b1;
41	
42	    // forward MEM-stage result (load data or ALU output) into ID stage
43	    assign forward_ctrl_A = (rs1use_ID && (rs1_ID != 5'd0) && (rs1_ID == rd_MEM)
44	                             && (hazard_optype_MEM != 2'b00)) ? 2'b01 : 2'b00;
45	    assign forward_ctrl_B = (rs2use_ID && (rs2_ID != 5'd0) && (rs2_ID == rd_MEM)
46	                             && (hazard_optype_MEM != 2'b00)) ? 2'b01 : 2'b00;
47	    // forward MEM-stage result to the store data of the EX-stage instruction
48	    assign forward_ctrl_ls = (rd_MEM != 5'd0) && (rd_MEM == rs2_EXE)
49	                             && (hazard_optype_MEM != 2'b00);
50	
51	endmodule

1	`timescale 1ns / 1ps
2	
3	
4	module CtrlUnit(
5	    input[31:0] inst,
6	    input cmp_res,
7	    output Branch, ALUSrc_A, ALUSrc_B, DatatoReg, RegWrite, mem_w,
8	        mem_r, rs1use, rs2use,
9	    output [1:0] hazard_optype,
10	    output [2:0] ImmSel, cmp_ctrl,
11	    output [3:0] ALUControl,
12	    output JALR, MRET,
13	
14	    output csr_rw, csr_w_imm_mux,
15	
16	    output[1:0] exp_vector
17	);
18	
19	    wire[6:0] funct7 = inst[31:25];
20	    wire[2:0] funct3 = inst[14:12];
21	    wire[6:0] opcode = inst[6:0];
22	
23	    wire Rop = opcode == 7'b0110011;
24	    wire Iop = opcode == 7'b0010011;
25	    wire Bop = opcode == 7'b1100011;
26	    wire Lop = opcode == 7'b0000011;
27	    wire Sop = opcode == 7'b0100011;
28	    wire CSRop = opcode == 7'b1110011;
29	
30	    wire funct7_0  = funct7 == 7'h0;
31	    wire funct7_32 = funct7 == 7'h20;
32	
33	    wire funct3_0 = funct3 == 3'h0;
34	    wire funct3_1 = funct3 == 3'h1;
35	    wire funct3_2 = funct3 == 3'h2;
36	    wire funct3_3 = funct3 == 3'h3;
37	    wire funct3_4 = funct3 == 3'h4;
38	    wire funct3_5 = funct3 == 3'h5;
39	    wire funct3_6 = funct3 == 3'h6;
40	    wire funct3_7 = funct3 == 3'h7;
41	
42	    wire ADD  = Rop & funct3_0 & funct7_0;
43	    wire SUB  = Rop & funct3_0 & funct7_32;
44	    wire SLL  = Rop & funct3_1 & funct7_0;
45	    wire SLT  = Rop & funct3_2 & funct7_0;
46	    wire SLTU = Rop & funct3_3 & funct7_0;
47	    wire XOR  = Rop & funct3_4 & funct7_0;
48	    wire SRL  = Rop & funct3_5 & funct7_0;
49	    wire SRA  = Rop & funct3_5 & funct7_32;
50	    wire OR   = Rop & funct3_6 & funct7_0;
51	    wire AND  = Rop & funct3_7 & funct7_0;
52	
53	    wire ADDI  = Iop & funct3_0;	
54	    wire SLTI  = Iop & funct3_2;
55	    wire SLTIU = Iop & funct3_3;
56	    wire XORI  = Iop & funct3_4;
57	    wire ORI   = Iop & funct3_6;
58	    wire ANDI  = Iop & funct3_7;
59	    wire SLLI  = Iop & funct3_1 & funct7_0;
60	    wire SRLI  = Iop & funct3_5 & funct7_0;
61	    wire SRAI  = Iop & funct3_5 & funct7_32;
62	
63	    wire BEQ = Bop & funct3_0;
64	    wire BNE = Bop & funct3_1;
65	    wire BLT = Bop & funct3_4;
66	    wire BGE = Bop & funct3_5;
67	    wire BLTU = Bop & funct3_6;
68	    wire BGEU = Bop & funct3_7;
69	
70	    wire LB =  Lop & funct3_0;
71	    wire LH =  Lop & funct3_1;
72	    wire LW =  Lop & funct3_2;
73	    wire LBU = Lop & funct3_4;
74	    wire LHU = Lop & funct3_5;
75	
76	    wire SB = Sop & funct3_0;
77	    wire SH = Sop & funct3_1;
78	    wire SW = Sop & funct3_2;
79	
80	    wire LUI   = opcode == 7'b0110111;
81	    wire AUIPC = opcode == 7'b0010111;
82	
83	    wire JAL  =  opcode == 7'b1101111;
84	    assign JALR = (opcode == 7'b1100111) && funct3_0;
85	
86	    wire CSRRW = CSRop & funct3_1;
87	    wire CSRRS = CSRop & funct3_2;
88	    wire CSRRC = CSRop & funct3_3;
89	    wire CSRRWI = CSRop & funct3_5;
90	    wire CSRRSI = CSRop & funct3_6;
91	    wire CSRRCI = CSRop & funct3_7;
92	
93	    assign MRET = inst == 32'b0011000_00010_00000_000_00000_1110011;
94	    wire ECALL = inst == 32'b0111_0011;
95	
96	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU;
97	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
98	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
99	    wire L_valid = LW | LH | LB | LHU | LBU;
100	    wire S_valid = SW | SH | SB;
101	    wire CSR_valid = CSRRW | CSRRS | CSRRC | CSRRWI | CSRRSI | CSRRCI;
102	
103	
104	    // generate control signals based on decoded instruction
105	    wire valid = R_valid | I_valid | B_valid | L_valid | S_valid | CSR_valid |
106	                 LUI | AUIPC | JAL | JALR | ECALL | MRET;
107	    wire illegal = ~valid;
108	
109	    assign Branch = (B_valid & cmp_res) | JAL | JALR;
110	
111	    assign ImmSel = (Iop | Lop | JALR) ? 3'b001 :     // I-type
112	                    Bop              ? 3'b010 :     // B-type
113	                    JAL              ? 3'b011 :     // J-type
114	                    Sop              ? 3'b100 :     // S-type
115	                    (LUI | AUIPC)    ? 3'b101 :     // U-type
116	                    3'b000;
117	
118	    assign cmp_ctrl = BEQ  ? 3'b001 :
119	                      BNE  ? 3'b010 :
120	                      BLT  ? 3'b011 :
121	                      BLTU ? 3'b100 :
122	                      BGE  ? 3'b101 :
123	                      BGEU ? 3'b110 : 3'b000;
124	
125	    assign ALUSrc_A = AUIPC | JAL | JALR;   // 1: PC, 0: rs1
126	    assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC | JAL | JALR; // 1: Imm, 0: rs2
127	
128	    assign ALUControl = (ADD | ADDI | L_valid | S_valid | AUIPC) ? 4'b0001 :
129	                        SUB          ? 4'b0010 :
130	                        (AND | ANDI) ? 4'b0011 :
131	                        (OR  | ORI)  ? 4'b0100 :
132	                        (XOR | XORI) ? 4'b0101 :
133	                        (SLL | SLLI) ? 4'b0110 :
134	                        (SRL | SRLI) ? 4'b0111 :
135	                        (SLT | SLTI) ? 4'b1000 :
136	                        (SLTU|SLTIU) ? 4'b1001 :
137	                        (SRA | SRAI) ? 4'b1010 :
138	                        (JAL | JALR) ? 4'b1011 :   // A + 4 (link address)
139	                        LUI          ? 4'b1100 :   // B passthrough
140	                        4'b0000;
141	
142	    assign DatatoReg = L_valid | CSR_valid; // 1: memory/CSR data, 0: ALU result
143	    assign RegWrite = R_valid | I_valid | L_valid | CSR_valid | LUI | AUIPC | JAL | JALR;
144	    assign mem_w = S_valid;
145	    assign mem_r = L_valid;
146	    assign rs1use = R_valid | I_valid | B_valid | L_valid | S_valid | JALR |
147	                    CSRRW | CSRRS | CSRRC;
148	    assign rs2use = R_valid | B_valid | S_valid;
149	
150	    localparam hazard_optype_ALU   = 2'd1;
151	    localparam hazard_optype_LOAD  = 2'd2;
152	    localparam hazard_optype_STORE = 2'd3;
153	    assign hazard_optype = (R_valid | I_valid | LUI | AUIPC | JAL | JALR) ? hazard_optype_ALU :
154	                           (L_valid | CSR_valid) ? hazard_optype_LOAD :
155	                           S_valid ? hazard_optype_STORE :
156	                           2'b00;
157	
158	    // CSR control signal generation
159	    assign csr_rw = CSR_valid;
160	    assign csr_w_imm_mux = CSRRWI | CSRRSI | CSRRCI;
161	    assign exp_vector = {illegal, ECALL};
162	
163	endmodule

