5	
6	    RV32core core(
7	        .debug_en(1'b0),
8	        .debug_step(1'b0),
9	        .debug_addr(7'b0),
10	        .debug_data(),
11	        .clk(clk),
12	        .rst(rst),
13	        .interrupter(1'b0)
14	    );
15	
16	    initial begin
17	        clk = 0;
