1	`timescale 1ns / 1ps
2	
3	module RAM_B(
4	    input [31:0] addra,
5	    input clka,      // normal clock
6	    input[31:0] dina,
7	    input wea, 
8	    output[31:0] douta,
9	    input[2:0] mem_u_b_h_w,
10	    input finish
11	);
12	
13	    localparam SIZE = 512;
14	    localparam ADDR_LINE = $clog2(SIZE);
15	    localparam SIM_UART_ADDR = 32'h10000000;
16	
17	    reg[7:0] data[0:SIZE-1];
18	
19	    initial	begin
20	        $readmemh("ram.mem", data);
21	    end
22	
23	    wire uart_w = wea & (addra == SIM_UART_ADDR);
24	    wire ram_w  = wea & (addra != SIM_UART_ADDR) & ~|addra[31:ADDR_LINE];
25	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
26	
27	    // write: byte / halfword / word, little endian
28	    always @ (negedge clka) begin
29	        if (ram_w) begin
30	            data[addr] <= dina[7:0];
31	            if (mem_u_b_h_w[0] | mem_u_b_h_w[1])
32	                data[addr + 1] <= dina[15:8];
33	            if (mem_u_b_h_w[1]) begin
34	                data[addr + 2] <= dina[23:16];
35	                data[addr + 3] <= dina[31:24];
36	            end
37	        end
38	    end
39	
40	    // read: word / halfword / byte with sign or zero extension
41	    assign douta = (addra == SIM_UART_ADDR) ? 32'b0 :
42	        |addra[31:ADDR_LINE] ? 32'b0 :
43	        mem_u_b_h_w[1] ? {data[addr + 3], data[addr + 2],
44	                    data[addr + 1], data[addr]} :
45	        mem_u_b_h_w[0] ? {mem_u_b_h_w[2] ? 16'b0 : {16{data[addr + 1][7]}},
46	                    data[addr + 1], data[addr]} :
47	        {mem_u_b_h_w[2] ? 24'b0 : {24{data[addr][7]}}, data[addr]};
48	
49	    // UART simulation: latch the character written to SIM_UART_ADDR,
50	    // print it when the store retires (finish).
51	    reg uart_addr_valid;
52	    reg[7:0] uart_char;
53	
54	    initial begin
55	        uart_addr_valid = 0;
56	        uart_char = 0;
57	    end
58	
59	    always @ (negedge clka) begin
60	        if (uart_w) begin
61	            uart_addr_valid <= 1'b1;
62	            uart_char <= dina[7:0];
63	        end
64	        else if (finish & uart_addr_valid) begin
65	            $write("%c", uart_char);
66	            uart_addr_valid <= 1'b0;
67	        end
68	    end
69	
70	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_jump(
4		input clk, EN, JALR,
5		input[3:0] cmp_ctrl,
6		input[31:0] rs1_data, rs2_data, imm, PC,
7		output[31:0] PC_jump, PC_wb,
8		output is_jump, finish
9	);
10	
11		wire cmp_res;
12	    reg state;
13	    assign finish = state == 1'b1;
14		initial begin
15	        state = 0;
16	    end
17	
18	    reg JALR_reg;
19	    reg[3:0] cmp_ctrl_reg;
20	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg, PC_reg;
21	
22	    // latch inputs on EN, one-cycle result
23	    always @(posedge clk) begin
24	        if (EN & ~state) begin
25	            JALR_reg <= JALR;
26	            cmp_ctrl_reg <= cmp_ctrl;
27	            rs1_data_reg <= rs1_data;
28	            rs2_data_reg <= rs2_data;
29	            imm_reg <= imm;
30	            PC_reg <= PC;
31	            state <= 1'b1;
32	        end
33	        else if (state) begin
34	            state <= 1'b0;
35	        end
36	    end
37	
38	    cmp_32 cmp(.a(rs1_data_reg), .b(rs2_data_reg),
39	        .ctrl(cmp_ctrl_reg[3:1]), .c(cmp_res));
40	
41	    // JALR: target = rs1 + imm; JAL/branch: target = PC + imm
42	    wire[31:0] base = JALR_reg ? rs1_data_reg : PC_reg;
43	    add_32 add_target(.a(base), .b(imm_reg), .c(PC_jump));
44	    add_32 add_return(.a(PC_reg), .b(32'd4), .c(PC_wb));
45	
46	    // unconditional jump or condition met
47	    assign is_jump = cmp_ctrl_reg[0] | cmp_res;
48	
49	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_mul(
4	    input clk, EN,
5	    input[31:0] A, B,
6	    output[31:0] res,
7	    output finish
8	);
9	
10	    reg[6:0] state;
11	    assign finish = state[0] == 1'b1;
12	    initial begin
13	        state = 0;
14	    end
15	
16	    reg[31:0] A_reg, B_reg;
17	
18	    // 64-cycle latency: 7'b100_0000 -> ... -> 7'b000_0001 -> 7'b000_0000
19	    always @(posedge clk) begin
20	        if (EN & ~|state) begin
21	            A_reg <= A;
22	            B_reg <= B;
23	            state <= 7'b100_0000;
24	        end
25	        else begin
26	            state <= {1'b0, state[6:1]};
27	        end
28	    end
29	
30	    wire[63:0] mulres;
31	    multiplier mul(.CLK(clk), .A(A_reg), .B(B_reg), .P(mulres));
32	
33	    assign res = mulres[31:0];
34	
35	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_div(
4	    input clk, EN,
5	    input[31:0] A, B,
6	    output[31:0] res,
7	    output finish
8	);
9	
10	    wire res_valid;
11	    wire[63:0] divres;
12	    
13	    reg state;
14	    assign finish = res_valid & state;
15	    initial begin
16	        state = 0;
17	    end
18	
19	    reg A_valid, B_valid;
20	    reg[31:0] A_reg, B_reg;
21	    initial begin
22	        A_valid = 0;
23	        B_valid = 0;
24	    end
25	
26	    // AXI-style handshake: raise valid for one cycle when EN,
27	    // then wait until the divider raises res_valid.
28	    always @(posedge clk) begin
29	        if (EN & ~state) begin
30	            A_reg <= A;
31	            B_reg <= B;
32	            A_valid <= 1'b1;
33	            B_valid <= 1'b1;
34	            state <= 1'b1;
35	        end
36	        else if (res_valid) begin
37	            A_valid <= 1'b0;
38	            B_valid <= 1'b0;
39	            state <= 1'b0;
40	        end
41	        else begin
42	            A_valid <= 1'b0;
43	            B_valid <= 1'b0;
44	        end
45	    end
46	
47	    divider div(
48	        .aclk(clk),
49	        .s_axis_dividend_tvalid(A_valid),
50	        .s_axis_dividend_tdata(A_reg),
51	        .s_axis_divisor_tvalid(B_valid),
52	        .s_axis_divisor_tdata(B_reg),
53	        .m_axis_dout_tvalid(res_valid),
54	        .m_axis_dout_tdata(divres)
55	    );
56	
57	    // quotient is in the upper 32 bits of the result bus
58	    assign res = divres[63:32];
59	
60	endmodule

1	`timescale 1ns / 1ps
2	
3	module FU_mem(
4	    input clk, EN, mem_w,
5	    input[2:0] bhw,
6	    input[31:0] rs1_data, rs2_data, imm,
7	    output[31:0] mem_data,
8	    output finish
9	);
10	
11	    reg[1:0] state;
12	    assign finish = state[0] == 1'b1;
13	    initial begin
14	        state = 0;
15	    end
16	
17	    reg mem_w_reg;
18	    reg[2:0] bhw_reg;
19	    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;
20	
21	    // 2-cycle latency: 2'b10 -> 2'b01 -> 2'b00
22	    always @(posedge clk) begin
23	        if (EN & ~|state) begin
24	            mem_w_reg <= mem_w;
25	            bhw_reg <= bhw;
26	            rs1_data_reg <= rs1_data;
27	            rs2_data_reg <= rs2_data;
28	            imm_reg <= imm;
29	            state <= 2'b10;
30	        end
31	        else begin
32	            state <= {1'b0, state[1]};
33	        end
34	    end
35	
36	    wire[31:0] addr;
37	    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));
38	
39	    RAM_B ram(.addra(addr), .clka(clk), .dina(rs2_data_reg),
40	        .wea(mem_w_reg & (|state)), .douta(mem_data), .mem_u_b_h_w(bhw_reg));
41	
42	endmodule

1	module cmu (
2	        // CPU side
3			input clk,
4			input rst,
5			input [31:0] addr_rw,
6			input en_r,
7			input en_w,
8	        input [2:0] u_b_h_w,
9			input [31:0] data_w,
10			output [31:0] data_r,
11			output stall,
12	
13	        // mem side
14			output reg mem_cs_o = 0,
15			output reg mem_we_o = 0,
16			output reg [31:0] mem_addr_o = 0,
17			input [31:0] mem_data_i,
18			output [31:0] mem_data_o,
19			input mem_ack_i,
20	
21	        // debug info
22	        output [2:0] cmu_state
23		);
24	
25	    `include "addr_define.vh"
26	
27	    reg [ADDR_BITS-1:0] cache_addr = 0;
28	    reg cache_load = 0;
29	    reg cache_store = 0;
30	    reg cache_edit = 0;
31	    reg [2:0] cache_u_b_h_w = 0;
32	    reg [WORD_BITS-1:0] cache_din = 0;
33	    wire cache_hit;
34	    wire [WORD_BITS-1:0] cache_dout;
35	    wire cache_valid;
36	    wire cache_dirty;
37	    wire [TAG_BITS-1:0] cache_tag;
38	
39	    cache CACHE (
40	        .clk(~clk),
41	        .rst(rst),
42	        .addr(cache_addr),
43	        .load(cache_load),
44	        .store(cache_store),
45	        .edit(cache_edit),
46	        .invalid(1'b0),
47	        .u_b_h_w(cache_u_b_h_w),
48	        .din(cache_din),
49	        .hit(cache_hit),
50	        .dout(cache_dout),
51	        .valid(cache_valid),
52	        .dirty(cache_dirty),
53	        .tag(cache_tag)
54	    );
55	
56	    localparam
57	        S_IDLE = 0,
58	        S_PRE_BACK = 1,
59	        S_BACK = 2,
60	        S_FILL = 3,
61	        S_WAIT = 4;
62	
63	    reg [2:0]state = 0;
64	    reg [2:0]next_state = 0;
65	    reg [ELEMENT_WORDS_WIDTH-1:0]word_count = 0;
66	    reg [ELEMENT_WORDS_WIDTH-1:0]next_word_count = 0;
67	    assign cmu_state = state;
68	
69	    always @ (posedge clk) begin
70	        if (rst) begin
71	            state <= S_IDLE;
72	            word_count <= 2'b00;
73	        end
74	        else begin
75	            state <= next_state;
76	            word_count <= next_word_count;
77	        end
78	    end
79	
80	    // state ctrl
81	    always @ (*) begin
82	        if (rst) begin
83	            next_state = S_IDLE;
84	            next_word_count = 2'b00;
85	        end
86	        else begin
87	            case (state)
88	                S_IDLE: begin
89	                    if (en_r || en_w) begin
90	                        if (cache_hit)
91	                            next_state = S_IDLE;
92	                        else if (cache_valid && cache_dirty)
93	                            next_state = S_PRE_BACK;
94	                        else
95	                            next_state = S_FILL;
96	                    end
97	                    next_word_count = 2'b00;
98	                end
99	
100	                S_PRE_BACK: begin
101	                    next_state = S_BACK;
102	                    next_word_count = 2'b00;
103	                end
104	
105	                S_BACK: begin
106	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})    // 2'b11 in default case
107	                        next_state = S_FILL;
108	                    else
109	                        next_state = S_BACK;
110	
111	                    if (mem_ack_i)
112	                        next_word_count = word_count + 1'b1;
113	                    else
114	                        next_word_count = word_count;
115	                end
116	
117	                S_FILL: begin
118	                    if (mem_ack_i && word_count == {ELEMENT_WORDS_WIDTH{1'b1}})
119	                        next_state = S_WAIT;
120	                    else
121	                        next_state = S_FILL;
122	
123	                    if (mem_ack_i)
124	                        next_word_count = word_count + 1'b1;
125	                    else
126	                        next_word_count = word_count;
127	                end
128	
129	                S_WAIT: begin
130	                    next_state = S_IDLE;
131	                    next_word_count = 2'b00;
132	                end
133	            endcase
134	        end
135	    end
136	    
137	    // cache ctrl
138	    always @ (*) begin
139	        case(state)
140	            S_IDLE, S_WAIT: begin
141	                cache_addr = addr_rw;
142	                cache_load = en_r;
143	                cache_edit = en_w;
144	                cache_store = 1'b0;
145	                cache_u_b_h_w = u_b_h_w;
146	                cache_din = data_w;
147	            end
148	            S_BACK, S_PRE_BACK: begin
149	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
150	                cache_load = 1'b0;
151	                cache_edit = 1'b0;
152	                cache_store = 1'b0;
153	                cache_u_b_h_w = 3'b010;
154	                cache_din = 32'b0;
155	            end
156	            S_FILL: begin
157	                cache_addr = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
158	                cache_load = 1'b0;
159	                cache_edit = 1'b0;
160	                cache_store = mem_ack_i;
161	                cache_u_b_h_w = 3'b010;
162	                cache_din = mem_data_i;
163	            end
164	        endcase
165	    end
166	    assign data_r = cache_dout;
167	
168	    // mem ctrl
169	    always @ (*) begin
170	        case (next_state)
171	            S_IDLE, S_PRE_BACK, S_WAIT: begin
172	                mem_cs_o = 1'b0;
173	                mem_we_o = 1'b0;
174	                mem_addr_o = 32'b0;
175	            end
176	
177	            S_BACK: begin
178	                mem_cs_o = 1'b1;
179	                mem_we_o = 1'b1;
180	                mem_addr_o = {cache_tag, addr_rw[ADDR_BITS-TAG_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
181	            end
182	
183	            S_FILL: begin
184	                mem_cs_o = 1'b1;
185	                mem_we_o = 1'b0;
186	                mem_addr_o = {addr_rw[ADDR_BITS-1:BLOCK_WIDTH], next_word_count, {ELEMENT_WORDS_WIDTH{1'b0}}};
187	            end
188	        endcase
189	    end
190	    assign mem_data_o = cache_dout;
191	
192	    // stall the CPU until the access completes; in S_WAIT the cache
193	    // re-access happens on the negedge, so the pipeline can advance
194	    // at the end of that cycle
195	    assign stall = (en_r | en_w) & ~(state == S_IDLE & cache_hit) & ~(state == S_WAIT);
196	
197	endmodule

