module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    input[2:0] mem_u_b_h_w,
    input finish
);

    localparam SIZE = 512;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    // TODO: implement — byte/halfword/word write logic
    // On negedge clka, if wea & addra != SIM_UART_ADDR:
    //   Always write dina[7:0] to data[addra].
    //   If halfword or word (mem_u_b_h_w[0] | mem_u_b_h_w[1]), also write dina[15:8].
    //   If word (mem_u_b_h_w[1]), also write dina[23:16] and dina[31:24].

    // TODO: implement — byte/halfword/word read logic with sign extension and UART
    // If addra == SIM_UART_ADDR, return 0.
    // Word: concatenate 4 bytes.
    // Halfword: sign/zero extend based on mem_u_b_h_w[2].
    // Byte: sign/zero extend based on mem_u_b_h_w[2].
    assign douta = 32'b0;

    // TODO: implement — UART simulation logic
    // Track uart_addr_valid and uart_char, $write on finish.

endmodule

