// Debug trace for lab6: ALU RS / FU activity in the first 25 cycles.
module lab6_dbg_tb;
    reg clk, rst;
    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(),
        .wb_addr(), .wb_data(), .clk(clk), .rst(rst), .interrupter(1'b0)
    );
    initial begin clk = 0; rst = 1; #10 rst = 0; end
    always #1 clk = ~clk;

    integer cycle = 0;
    integer e;
    always @(posedge clk) if (!rst) begin
        cycle = cycle + 1;
        if (cycle >= 4 && cycle <= 22) begin
            $write("cyc %0d: ISpc=%h en_FU=%b fu_busy=%b finish=%b done=%b cdb=%h:%h |",
                   cycle, core.PC_IS, core.FU_ALU_EN, core.rs_alu.fu_busy,
                   core.FU_ALU_finish, core.done_record, core.cdb_rs_num, core.cdb_data);
            for (e = 0; e < 3; e = e + 1)
                $write(" e%0d[B=%b Q1=%h Q2=%h V1=%h pc=%h disp=%b]", e,
                       core.rs_alu.entry[e][0], core.rs_alu.entry[e][15:8],
                       core.rs_alu.entry[e][23:16], core.rs_alu.entry[e][63:32],
                       core.rs_alu.entry[e][159:128], core.rs_alu.dispatched[e]);
            $display("");
        end
        if (cycle > 22) $finish;
    end
endmodule

